//! Turns validated providers into Rust source for `cradle-backends/build.rs`.

use std::fmt::Write;

use crate::{Auth, Backend, CliAgent, HttpApi, ProviderSpec};

/// Generate a `builtin_providers()` function returning `specs`.
///
/// The output refers to `::cradle_provider_spec`, so the including crate must depend on it.
pub fn to_rust_source(specs: &[ProviderSpec]) -> String {
    let mut out = String::from(
        "// @generated by cradle-backends/build.rs from providers.toml. Do not edit.\n\n\
         pub fn builtin_providers() -> ::std::vec::Vec<::cradle_provider_spec::ProviderSpec> {\n    \
         use ::cradle_provider_spec::*;\n    \
         ::std::vec![\n",
    );
    for spec in specs {
        writeln!(
            out,
            "        ProviderSpec {{ id: {}, backend: {} }},",
            string(&spec.id),
            backend(&spec.backend)
        )
        .unwrap();
    }
    out.push_str("    ]\n}\n");
    out
}

fn backend(backend: &Backend) -> String {
    match backend {
        Backend::Http(http) => {
            let api = match http.api {
                HttpApi::Anthropic => "HttpApi::Anthropic",
                HttpApi::OpenaiCompatible => "HttpApi::OpenaiCompatible",
            };
            let auth = match &http.auth {
                Auth::None => "Auth::None".to_owned(),
                Auth::ApiKey { env } => format!("Auth::ApiKey {{ env: {} }}", string(env)),
            };
            let headers = http
                .headers
                .iter()
                .map(|(k, v)| format!("({}, {})", string(k), string(v)))
                .collect::<Vec<_>>()
                .join(", ");
            let c = &http.capabilities;
            format!(
                "Backend::Http(HttpProvider {{ api: {api}, base_url: {}, auth: {auth}, \
                 models: {}, default_model: {}, headers: ::std::vec![{headers}], \
                 capabilities: Capabilities {{ tools: {}, streaming: {}, prompt_caching: {}, \
                 reasoning: {} }} }})",
                string(&http.base_url),
                strings(&http.models),
                option(&http.default_model),
                c.tools,
                c.streaming,
                c.prompt_caching,
                c.reasoning,
            )
        }
        Backend::Cli(cli) => {
            let agent = match cli.agent {
                CliAgent::ClaudeCode => "CliAgent::ClaudeCode",
                CliAgent::Codex => "CliAgent::Codex",
            };
            format!(
                "Backend::Cli(CliProvider {{ agent: {agent}, binary: {}, version: {}, \
                 models: {}, default_model: {} }})",
                string(&cli.binary),
                option(&cli.version),
                strings(&cli.models),
                option(&cli.default_model),
            )
        }
    }
}

/// `Debug` for `str` produces a valid Rust string literal (quotes and escapes included).
fn string(s: &str) -> String {
    format!("::std::string::String::from({s:?})")
}

fn strings(items: &[String]) -> String {
    let items: Vec<String> = items.iter().map(|s| string(s)).collect();
    format!("::std::vec![{}]", items.join(", "))
}

fn option(value: &Option<String>) -> String {
    match value {
        Some(s) => format!("::std::option::Option::Some({})", string(s)),
        None => "::std::option::Option::None".to_owned(),
    }
}
